def handle(context):
    text = str(context.get('prompt_text') or '').strip()
    normalized = ' '.join(text.lower().split())
    if not normalized:
        return {'handled': True, 'assistant_text': 'Send a message and Entrance will keep it in this conversation first.'}
    if normalized in {'ping', 'hello', 'hi', 'help', 'status'} or normalized.startswith('status '):
        return {'handled': True, 'assistant_text': 'Entrance is active. Messages stay in Entrance first; its agents can coordinate delegated work when needed.'}
    return {'handled': False}
